select t.*, t.project_name, t.project_number, t.project_number as project_id_n, t.bank_id, (SELECT a.bank_branch_name FROM csh_bank_account a WHERE a.bank_account_id = t.bank_id) bank_id_n, (SELECT a.bank_account_num FROM csh_bank_account a WHERE a.bank_account_id = t.bank_id) bank_account_num, (SELECT a.bank_account_name FROM csh_bank_account a WHERE a.bank_account_id = t.bank_id) bank_account_name, (SELECT a.bank_type_new FROM csh_bank_account a WHERE a.bank_account_id = t.bank_id) bank_type_new, (SELECT f.company_full_name FROM csh_bank_account a,fnd_company f WHERE a.bank_account_id = t.bank_id and a.company_id = f.company_id) company_full_name, (SELECT (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'BANK_TYPE_NEW' AND scb.CODE_ID = scv.CODE_ID and scv.value = a.bank_type_new) FROM csh_bank_account a WHERE a.bank_account_id = t.bank_id) bank_type_new_n, (SELECT scv.meaning FROM sys_code_b scb, sys_code_value_b scv WHERE scb.CODE = 'CSH.PAYMENT_METHOD' AND scb.CODE_ID = scv.CODE_ID and scv.value = t.payment_method)payment_method_n from jc_fund_filling_req_detail t
